// v91.17.283.49 · 1.0.10 data item 5 · the night minimum is served from the better of the corrected chain and the raw model, per variable /
// zone / lead, by the stored evidence (data/skill-evidence.json servedChoice, generated by scripts/gen/gen_evidence.py from the SCI2821 T1
// pairs: Tmin corrected 1.53 / 1.58 / 1.64 C vs raw 1.48 / 1.49 / 1.55 C at days 1-3, difference interval excluding 0; Tmax corrected better).
// Fails on 1.0.9: no servedChoice in the evidence, no skillchoice stage in the chain, the corrected night minimum is served.
// usage: node scripts/tests28349dat/skillchoice113.test.mjs
import { join, dirname } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { readFileSync, existsSync, mkdtempSync, writeFileSync, copyFileSync, mkdirSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { spawnSync } from 'node:child_process';
const APP = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
let pass = 0, fail = 0; const ok = (c, n, d = '') => { if (c) { pass++; console.log('PASS ' + n + (d ? ' - ' + d : '')); } else { fail++; console.log('FAIL ' + n + (d ? ' - ' + d : '')); } };
const end = () => { console.log(`\n${pass} passed, ${fail} failed`); process.exit(fail ? 1 : 0); };
const imp = (rel) => import(pathToFileURL(join(APP, rel)).href);
/* v91.17.283.49 merge: the swap is OFF unless NIGRAAN_SKILL_CHOICE=1 (real-forecast check, skillchoice.mjs note); the mechanics below run with it on */
process.env.NIGRAAN_SKILL_CHOICE = '1';
const E = JSON.parse(readFileSync(join(APP, 'data', 'skill-evidence.json'), 'utf8'));
ok(E.servedChoice && Array.isArray(E.servedChoice.cells), 'the evidence file carries servedChoice (generated, not typed)');
/* the file is what the generator makes from the evidence in the tree (no hand edit) */
const T = mkdtempSync(join(tmpdir(), 'sc113-'));
const g = spawnSync('python3', ['-I', join(APP, 'scripts/gen/gen_evidence.py'), join(APP, 'data/evidence/sci2821'), join(T, 'se.json'), join(APP, 'data/evidence/heat2838')], { encoding: 'utf8' });
ok(g.status === 0 && existsSync(join(T, 'se.json')) && readFileSync(join(T, 'se.json'), 'utf8') === readFileSync(join(APP, 'data', 'skill-evidence.json'), 'utf8'), 'data/skill-evidence.json == gen_evidence.py output (byte for byte)', g.stderr.slice(0, 200));
if (!existsSync(join(APP, 'server/api/skillchoice.mjs'))) { ok(false, 'server/api/skillchoice.mjs exists'); end(); }
const SC = await imp('server/api/skillchoice.mjs');
const S = JSON.parse(readFileSync(join(APP, 'server/api/../../data/evidence/sci2821/summary.json'), 'utf8')).findings.T1_strict_daily_L1_L2_L3;
for (const L of [1, 2, 3]) {
  ok(SC.choiceOf(E, 'tmin', 'plains', L) === (S.Tmin_mae[L - 1] > S.Tmin_raw_mae[L - 1] ? 'raw' : 'corrected'), 'Tmin plains day ' + L + ': ' + SC.choiceOf(E, 'tmin', 'plains', L) + ' (corrected ' + S.Tmin_mae[L - 1] + ' vs raw ' + S.Tmin_raw_mae[L - 1] + ' C)');
  ok(SC.choiceOf(E, 'tmax', 'plains', L) === 'corrected', 'Tmax plains day ' + L + ': corrected (corrected ' + S.Tmax_mae[L - 1] + ' vs raw ' + S.Tmax_raw_mae[L - 1] + ' C)');
}
ok(SC.choiceOf(E, 'tmin', 'plains', 0) === 'corrected' && SC.choiceOf(E, 'tmin', 'mountain', 1) === 'corrected', 'no evidence (day 0, mountain): the corrected chain stays');
/* a hand edit of 'served' alone cannot switch a cell (the rule is re-checked from the stored figures) */
const E2 = JSON.parse(JSON.stringify(E)); E2.servedChoice.cells.find((c) => c.variable === 'tmax').served = ['raw', 'raw', 'raw'];
ok(SC.choiceOf(E2, 'tmax', 'plains', 1) === 'corrected', 'a typed "raw" without the evidence behind it is ignored');
const E3 = JSON.parse(JSON.stringify(E)); E3.servedChoice.cells.find((c) => c.variable === 'tmin').diffIntervalExcludesZero = false;
ok(SC.choiceOf(E3, 'tmin', 'plains', 1) === 'corrected', 'without a significant difference the corrected chain stays');
/* the chain step on a synthetic plains answer: corrected night 2 C warmer than raw; days 1-3 get the raw night, day 0 and day hours keep the corrected values */
const today = new Date(Date.now() + 5 * 3600e3).toISOString().slice(0, 10), base = Date.parse(today + 'T00:00:00Z');
const time = [], T0 = [], Tc = []; for (let h = 0; h < 5 * 24; h++) { const t = new Date(base + h * 3600e3).toISOString().slice(0, 16); time.push(t); const hh = h % 24; const raw = 15 + 8 * Math.sin((hh - 9) / 24 * 2 * Math.PI); T0.push(Math.round(raw * 10) / 10); Tc.push(Math.round((raw + 2) * 10) / 10); }
const loc = { utc_offset_seconds: 18000, hourly: { time, temperature_2m: Tc.slice() } }; Object.defineProperty(loc, '__startT', { value: T0, enumerable: false });
const n = SC.applySkillChoice(loc, 31.52, 74.35, { evidence: { ready: true, ...E }, zone: 'plains', record: true });
const { dayNight } = await imp('server/api/dayext.mjs');
const dayOf = (k) => new Date(base + k * 864e5).toISOString().slice(0, 10);
const mins = (arr, k) => Math.min(...arr.slice(k * 24, k * 24 + 24));
ok(n > 0 && loc.agn_skill_choice && loc.agn_skill_choice.days.map((d) => d.lead).join() === '1,2,3', 'applied on days 1-3 only', JSON.stringify(loc.agn_skill_choice && loc.agn_skill_choice.days.map((d) => [d.lead, d.hours])));
for (const k of [1, 2, 3]) ok(mins(loc.hourly.temperature_2m, k) === mins(T0, k), 'day ' + k + ': the served minimum is the raw minimum (' + mins(loc.hourly.temperature_2m, k) + ' C, corrected was ' + mins(Tc, k) + ')');
ok(mins(loc.hourly.temperature_2m, 0) === mins(Tc, 0) && mins(loc.hourly.temperature_2m, 4) === mins(Tc, 4), 'day 0 and day 4 keep the corrected values (no evidence)');
const dn = dayNight(31.52, 74.35, dayOf(1)), mid = dn.day.filter((h) => h !== Math.min(...dn.day) && h !== Math.max(...dn.day));
ok(mid.every((h) => loc.hourly.temperature_2m[24 + h] === Tc[24 + h]), 'day 1 daytime hours (and so the maximum) keep the corrected values');
const steps = loc.hourly.temperature_2m.slice(24, 96).map((v, i, a) => (i ? Math.abs(v - a[i - 1]) : 0));
ok(Math.max(...steps) <= Math.max(...Tc.slice(24, 96).map((v, i, a) => (i ? Math.abs(v - a[i - 1]) : 0))) + 1.01, 'no step larger than half the correction at sunrise / sunset (joins averaged)');
{ delete process.env.NIGRAAN_SKILL_CHOICE; const l3 = { utc_offset_seconds: 18000, hourly: { time, temperature_2m: Tc.slice() } }; Object.defineProperty(l3, '__startT', { value: T0, enumerable: false, configurable: true });
  ok(SC.applySkillChoice(l3, 31.52, 74.35, { evidence: { ready: true, ...E }, zone: 'plains' }) === 0, '1.0.10 default (NIGRAAN_SKILL_CHOICE unset): off, the 1.0.9 corrected curve is served'); }
process.env.NIGRAAN_SKILL_CHOICE = '0'; const loc2 = { utc_offset_seconds: 18000, hourly: { time, temperature_2m: Tc.slice() } }; Object.defineProperty(loc2, '__startT', { value: T0, enumerable: false });
ok(SC.applySkillChoice(loc2, 31.52, 74.35, { evidence: { ready: true, ...E }, zone: 'plains' }) === 0, 'NIGRAAN_SKILL_CHOICE=0: off'); delete process.env.NIGRAAN_SKILL_CHOICE;
/* wired in the served chain after the weather MOS, before the live layers */
const V = readFileSync(join(APP, 'server/api/verification.mjs'), 'utf8');
const st = JSON.parse(((V.match(/const CHAIN_STAGES = (\[[^\]]*\])/) || [])[1] || '[]').replace(/'/g, '"'));
ok(st.indexOf('skillchoice') === st.indexOf('wxmos') + 1 && st.indexOf('skillchoice') < st.indexOf('live') && /skillchoice: \(\) => base && applySkillChoice\(/.test(V), 'chain stage: wxmos -> skillchoice -> ... live', st.join(','));
end();
